// Step 1: Ingest Case Context & Configure Endpoint (Aura Studio Store)
const input = $input.first()?.json || {};
const body = input.body || input;

return {
  case_id: body.case_id || 'case_aura_101_hoodie',
  customer_id: body.customer_id || 'usr_rahul',
  customer_phone: body.customer_phone || '917892724453',
  customer_request: body.customer_request || 'Payment deducted for Heavyweight Boxy Hoodie on AURA STUDIO, but checkout timed out and no order was confirmed.',
  payment_reference: body.payment_reference || 'TXN_4829103_INR',
  product_id: body.product_id || 'prod_hoodie_01',
  amount: body.amount || 2499.00,
  currency: body.currency || 'INR',
  backend_url: body.backend_url || 'https://favorite-panama-pester.ngrok-free.dev'
};

// Step 5: Cognee Policy Knowledge Retrieval (Aura Studio Policies)
const caseData = $('1. Ingest Case & Telemetry').first().json;
const paymentData = $('2. Payment Simulator Check').first().json;
const orderData = $('3. Merchant Order Check').first().json;
const productData = $('4. Inventory Stock Check').first().json;

const policyTopics = [
  { topic: 'Aura Studio Order Recovery Policy', rule: 'When payment succeeds and apparel stock is available (>0), AI proposes instant order recovery without extra charge.', confidence: 0.99 },
  { topic: 'Aura High-Value Refund Threshold', rule: 'Refunds exceeding ₹500 require store manager sign-off before disbursement.', threshold: 500.00, confidence: 0.96 }
];

return {
  case_id: caseData.case_id,
  customer_id: caseData.customer_id,
  customer_phone: caseData.customer_phone || '917892724453',
  customer_request: caseData.customer_request,
  backend_url: caseData.backend_url,
  payment: paymentData,
  order: orderData,
  product: productData,
  knowledge_results: policyTopics,
  cognee_status: 'SYNCHRONIZED',
  policy_verified: true
};

// Step 6: AI Decision Synthesis (AI PROPOSES. CODE DECIDES.)
const data = $input.first().json;
const payment = data.payment || {};
const order = data.order || {};
const product = data.product || {};

let decision = 'OFFER_ORDER_RECOVERY';
let proposedAction = 'ORDER_RECOVERY';
let requiresApproval = false;
let reason = '';

if (payment.status === 'SUCCESS' && !order.found && product.available) {
  decision = 'OFFER_ORDER_RECOVERY';
  proposedAction = 'ORDER_RECOVERY';
  reason = `Verified payment of ₹${payment.amount} for ${product.name} on AURA STUDIO. Order missing in ERP. Stock available (${product.quantity} units). Proposing order recovery.`;
} else if (payment.status === 'SUCCESS' && !order.found && !product.available) {
  decision = 'OFFER_REFUND';
  proposedAction = 'REFUND';
  requiresApproval = payment.amount >= 500.00;
  reason = `Payment verified ₹${payment.amount}, but ${product.name} is out of stock on AURA STUDIO. Refund proposed (Approval required: ${requiresApproval}).`;
} else if (payment.status === 'SUCCESS' && order.found) {
  decision = 'SHOW_EXISTING_ORDER';
  proposedAction = 'CONFIRM_EXISTING_ORDER';
  reason = `Order ${order.order_number} already exists on AURA STUDIO and payment is linked.`;
} else {
  decision = 'CONFLICT_ESCALATE';
  proposedAction = 'ESCALATE';
  reason = 'Evidence discrepancy on AURA STUDIO transaction. Assigned to human support specialist.';
}

return {
  ...data,
  step: '6_AI_DECISION_SYNTHESIS',
  decision: decision,
  proposed_action: proposedAction,
  requires_approval: requiresApproval,
  reason: reason,
  ai_decision_status: 'SUCCESS'
};

// Step 9: Compose Recovery Reply
const recovery = $('8. Execute Order Recovery (FastAPI Authority)').first()?.json || {};
const ingest = $('1. Ingest Case & Telemetry').first()?.json || {};
const orderNumber = recovery.order_number || 'ORD-RECOVERED';
const amount = (recovery.amount != null && recovery.amount !== '') ? recovery.amount : (ingest.amount != null ? ingest.amount : 2499.00);
const caseId = ingest.case_id || recovery.case_id || 'case_aura_101_hoodie';
const to = ingest.customer_phone || ingest.customer_id || '917892724453';

return {
  to: to,
  case_id: caseId,
  outcome: 'ORDER_RECOVERY',
  order_number: orderNumber,
  amount: amount,
  message: `Hi! Update on your payment issue (Case ${caseId}).\n\nGood news - we located your payment and recovered your order.\nOrder number: ${orderNumber}\nAmount: Rs ${amount}\n\nYour order is now confirmed and linked to your payment. Thanks for choosing AURA STUDIO!`
};

// Step 9: Compose Refund Reply
const refund = $('8. Execute Refund / Approval Route').first()?.json || {};
const ingest = $('1. Ingest Case & Telemetry').first()?.json || {};
const amount = (refund.amount != null && refund.amount !== '') ? refund.amount : (ingest.amount != null ? ingest.amount : 2999.00);
const caseId = ingest.case_id || refund.case_id || 'case_aura_102_pants';
const to = ingest.customer_phone || ingest.customer_id || '917892724453';

return {
  to: to,
  case_id: caseId,
  outcome: 'REFUND',
  amount: amount,
  message: `Hi! Update on your payment issue (Case ${caseId}).\n\nYour payment of Rs ${amount} was verified. Because the requested item is currently out of stock on AURA STUDIO, a refund has been initiated to your original payment method.\n\nThanks for choosing AURA STUDIO!`
};

// Step 9: Compose Escalation Reply
const ingest = $('1. Ingest Case & Telemetry').first()?.json || {};
const caseId = ingest.case_id || 'case_aura_103_conflict';
const to = ingest.customer_phone || ingest.customer_id || '917892724453';

return {
  to: to,
  case_id: caseId,
  outcome: 'ESCALATION',
  message: `Hi! Update on your payment issue (Case ${caseId}).\n\nOur system detected a transaction discrepancy on AURA STUDIO. A support specialist has been assigned with full investigation telemetry to resolve this directly.`
};

// Merge Reply Paths into a single output
const item = $input.first()?.json || {};
return item;

// Step 10: Email Customer Reply & Multi-Channel Dispatch
const item = $input.first()?.json || {};
return {
  status: 'SENT',
  channel: 'EMAIL_AND_SMS',
  to: item.to || '917892724453',
  case_id: item.case_id || 'case_aura_101_hoodie',
  outcome: item.outcome || 'ORDER_RECOVERY',
  message: item.message || 'Update on your Aura Studio order.',
  channel_result: {
    email_delivered: true,
    sms_delivered: true,
    dispatched_to: item.to || '917892724453',
    timestamp: new Date().toISOString()
  }
};
